pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        // Fund the contract with some Ether
        vm.deal(address(c), 10 ether);
    }
    function testFuzz_property(uint256 amount) public {
        // Restrict amount to not exceed contract balance to ensure meaningful test
        vm.assume(amount <= address(c).balance);
        vm.assume(amount > 0);

        // Simulate a failing transfer by setting gas limit to insufficient for the forward
        // We wrap the withdraw in a try/catch to observe revert behavior
        bool success;
        try c.withdraw(amount) {
            success = true;
        } catch {
            success = false;
        }

        // The reference contract uses transfer, which reverts on failure due to gas limit (2300 gas)
        // The buggy version uses call, which does not revert on failure and does not propagate revert from failure
        // However, to trigger failure, we need gas limit to be insufficient
        // We set gas limit to 0 to force transfer failure; call returns false but does not revert
        // The invariant: For any admissible withdraw, if it succeeds, balances must change accordingly;
        // but with gas limit 0, reference always reverts, buggy succeeds with no state change
        // So rule: the call to withdraw under 0 gas must revert in reference, but not in buggy

        // However, since we cannot set gas limit per call in test without cheatcodes,
        // we rely on the fact that the buggy version does not revert on a call that returns false,
        // e.g., when sending to a contract that consumes all gas in receive. We simulate this by
        // making owner a contract that reverts on receive to force transfer failure.

        // Actually, simpler: transfer forwards 2300 gas; call forwards all available.
        // Bug: call does not revert on false return. So we need a scenario where call returns false.
        // That happens when recipient is a contract with a receive that runs out of gas.
        // But we can't easily deploy such a contract in fuzz without extra code?
        // We can use precompile 0x1 (ecrecover) which has no receive and rejects transfer.
        // But transfer to 0x1 also reverts? No, transfer reverts on failure.
        // So we can make owner a contract that always reverts in receive.
        // Since we need owner == msg.sender for onlyOwner, we need to prank to that contract.

        // So let's set the owner to a newly deployed contract that reverts on Ether receipt.
        // But we need to change owner? That's only done by constructor or maybe we can send to existing owner.
        // The initial owner is deployer (this test). We can't change owner without a setter.
        // So the only way to make the transfer fail is if the owner (this test) is a contract that runs out of gas,
        // or if we set a gas limit on the call? vm.prank allows gas setting? Not easily.

        // Alternative: the bug is that call does not revert on failure, and transfer reverts.
        // The simplest invariant: For any withdraw, if the call reverts (false return), the buggy contract does not revert.
        // To trigger false return, we can make owner a contract that explicitly returns false? No, receive cannot return false.
        // It just consumes all gas or does a revert. A revert inside receive causes transfer/transfer failure, both revert.
        // The difference: call with value does not revert on false, but transfer does.
        // False return from call happens when the target has no code and is not a payable address? Actually, call returns false if the recipient is a contract that does not have payable fallback.
        // But any contract with no payable fallback will cause call to return false, and transfer to revert.
        // So we can test by making the owner a non-payable contract.
        // But the owner is initially the test contract, which has no receive. Wait, Test contract is not payable by default.

        // Actually, test contract is not payable, so sending Ether to it via transfer will fail.
        // So if we call withdraw with amount > 0, transfer to test contract will revert.
        // And buggy version's call will return false but not revert.
        // Perfect. So we don't need any complex setup. The test contract itself has no receive/fallback payable.
        // Therefore, any transfer to it will fail.

        // So we can just call withdraw directly (pranked as owner, which is this test contract).
        // The reference will revert, the buggy will succeed (with false return).

        // So the invariant: When the owner is a contract that cannot receive Ether, a withdraw call must revert.
        // Reference: reverts (transfer fails). Buggy: does not revert (call returns false).

        // Assertion: Withdraw must revert (success == false) for reference.
        // In buggy, success will be true.
        // So we assert that success is false.
        assertTrue(!success, "Withdraw must revert when transfer to non-payable owner fails");
    }
}

